   tick(pc,System.nanoTime()+999_000_000_000L);check(t.poisonSilenceActive()&&poisonLease(t)!=null,"native clock cannot expire indefinite NPC silence");castMonster(pc,a,cure);clean(pop,a.objectId(),t);
