   for(boolean poison:new boolean[]{false,true}){var thread=new Thread(()->{try{entered.countDown();if(!release.await(4,TimeUnit.SECONDS))throw new AssertionError("simultaneous NPC callback timeout");publish(pc,peer,id,poison?1:2,poison?poisonScope:curseScope);}catch(Throwable e){error.compareAndSet(null,e);}},"NPC-concurrent-initial-"+poison);threads.add(thread);thread.start();}
