 static void socketBarrier(ClientSession pc,ClassicWorldMonsterPopulation pop,BattleTimedStatus t,Task work,Task inspect)throws Exception{
  var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var error=new AtomicReference<Throwable>();var once=new AtomicBoolean();Socket original=(Socket)get(pc,"socket");Socket watched=new Socket(){public OutputStream getOutputStream()throws IOException{return new FilterOutputStream(original.getOutputStream()){public void write(byte[] b,int off,int len)throws IOException{if(Thread.holdsLock(t)||Thread.holdsLock(pop))throw new AssertionError("NPC silence network under status/population monitor");if(Thread.currentThread().getName().equals("NPC-silence-socket")&&ownsEither(t)&&once.compareAndSet(false,true)){entered.countDown();try{if(!release.await(4,TimeUnit.SECONDS))throw new AssertionError("NPC silence socket timeout");}catch(InterruptedException e){throw new AssertionError(e);}}out.write(b,off,len);}public void write(int b)throws IOException{out.write(b);}};}};
  set(pc,"socket",watched);var thread=new Thread(()->{try{work.run();}catch(Throwable e){error.set(e);entered.countDown();}},"NPC-silence-socket");thread.start();try{check(entered.await(4,TimeUnit.SECONDS)&&error.get()==null,"actual NPC silence publisher reached payload barrier: "+error.get());inspect.run();}finally{release.countDown();thread.join(4000);set(pc,"socket",original);watched.close();}check(!thread.isAlive()&&error.get()==null,"actual NPC silence publisher completes without deadlock: "+error.get());
 }
